// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是按仓库阈值配置相对仓库根的路径。
const thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值按仓库配置在仓库根的 config/thresholds.json 里，**每次调用**从磁盘读取
// （不 embed、不缓存），所以运维改文件即可生效，不需要重新构建。
// 配置里没有的仓库回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 解析「仓库名 → 阈值」配置。
// 文件缺失、读不了或内容不合法时返回 nil，即视为没有任何按仓库配置。
func loadThresholds() map[string]int {
	raw, err := os.ReadFile(thresholdsPath())
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(raw, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// thresholdsPath 从当前工作目录向上找到模块根（含 go.mod 的目录），拼出配置路径。
// Go 把测试的 cwd 设为包目录，所以不能假设进程从仓库根启动；
// 找不到模块根时退回相对当前目录的路径。
func thresholdsPath() string {
	dir, err := os.Getwd()
	if err != nil {
		return thresholdsFile
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, thresholdsFile)
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return thresholdsFile
		}
		dir = parent
	}
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

